// Фикстура теста русских имён API: вся сцена написана по-русски.
//
// Проверяем главное: узел с русским тегом получает КАНОНИЧЕСКИЙ тег (иначе его
// не узнают отрисовка и селекторы), русские атрибуты доходят до подсистем,
// методы-псевдонимы работают, а пространства имён — те же объекты.
$.ready(() => {
    $.мир.gravity(0, 0).color('#101820').bounds(0, 0, 800, 600);

    $('<прямоугольник>', { id: 'фон' }).в(400, 300).размер(800, 600)
        .цвет('#101820').добавитьВ($.мир);

    // Атрибуты по-русски: их переводят до создания узла.
    $('<свет>', { id: 'фонарь', 'радиус': 260, 'яркость': 1, 'цвет': '#ffd9a0', 'тени': true })
        .в(200, 300).смешать('add').добавитьВ($.мир);

    $('<игрок>', { id: 'герой' }).в(100, 300).скорость(220).добавитьВ($.мир);
    $('<враг>', { id: 'злодей' }).в(500, 300).добавитьВ($.мир);

    $('<туман>', { id: 'дымка', 'плотность': 0.3, 'полосы': 3 })
        .в(400, 300).размер(800, 600).добавитьВ($.мир);
});
